// ===== Keystone shared library (generated from ops/lib; do not edit here) =====
const __KS = (() => {
  const defs = {
  'calc': function (module, exports, require) {
'use strict';
// Website quote calculator (free but email-verified): validation, codes, rate limits, free-mail flag, results.
// Pure functions, unit-tested; the n8n workflow "KS Website Calculator" does the I/O.
const P = require('./pricing');

const LIMIT_PER_DAY = 3;
const CODE_MINUTES = 15;
const MAX_ATTEMPTS = 3;
const BANDS = { under500k: 'Under £500k', '500k-1m': '£500k–£1M', '1m-3m': '£1M–£3M', '3m-10m': '£3M–£10M', over10m: 'Over £10M' };
const SERVICE_KEYS = ['invoicing', 'phone', 'quotes', 'reporting'];
const FREE_MAIL = ['gmail.com', 'googlemail.com', 'hotmail.com', 'hotmail.co.uk', 'outlook.com', 'outlook.co.uk', 'live.com', 'live.co.uk', 'msn.com', 'yahoo.com', 'yahoo.co.uk', 'ymail.com', 'icloud.com', 'me.com', 'mac.com', 'aol.com', 'aol.co.uk', 'btinternet.com', 'sky.com', 'virginmedia.com', 'talktalk.net', 'protonmail.com', 'proton.me', 'gmx.com', 'gmx.co.uk', 'mail.com', 'zoho.com'];

// Small non-cryptographic hash (cyrb53) with a secret salt: enough for 15-minute 6-digit codes with 3 attempts.
function hash(str, salt) {
  const s = String(salt || '') + '|' + String(str || '');
  let h1 = 0xdeadbeef, h2 = 0x41c6ce57;
  for (let i = 0; i < s.length; i++) { const ch = s.charCodeAt(i); h1 = Math.imul(h1 ^ ch, 2654435761); h2 = Math.imul(h2 ^ ch, 1597334677); }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(36);
}
function randomCode() { return String(Math.floor(100000 + Math.random() * 900000)); }
function randomId(n = 24) { const c = 'abcdefghijkmnpqrstuvwxyz23456789'; let s = ''; for (let i = 0; i < n; i++) s += c[Math.floor(Math.random() * c.length)]; return s; }

function parseBody(b) {
  if (typeof b === 'string') { try { return JSON.parse(b); } catch (e) { return {}; } }
  if (b && typeof b === 'object') {
    const keys = Object.keys(b);
    // text/plain bodies can arrive as {"<json>": ""}
    if (keys.length === 1 && keys[0].startsWith('{') && !b[keys[0]]) { try { return JSON.parse(keys[0]); } catch (e) { return b; } }
    return b;
  }
  return {};
}

function clientIp(headers) {
  const h = headers || {};
  return String(h['cf-connecting-ip'] || h['x-real-ip'] || String(h['x-forwarded-for'] || '').split(',')[0] || '').trim();
}

function isFreeMail(email) { const d = String(email || '').split('@')[1] || ''; return FREE_MAIL.includes(d.toLowerCase()); }

function validateStart(b) {
  const x = {
    name: String(b.name || '').trim().slice(0, 100), email: String(b.email || '').trim().toLowerCase().slice(0, 200),
    company: String(b.company || '').trim().slice(0, 150), revenueBand: String(b.revenueBand || ''),
    services: (Array.isArray(b.services) ? b.services : []).filter((s) => SERVICE_KEYS.includes(s)), consent: b.consent === true,
    honeypot: String(b.website || b.url || '').trim(),
  };
  const errors = [];
  if (x.name.length < 2) errors.push('Please enter your name.');
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(x.email)) errors.push('Please enter a valid business email.');
  if (x.company.length < 2) errors.push('Please enter your company name.');
  if (!BANDS[x.revenueBand]) errors.push('Please choose your annual revenue.');
  return { x, errors, isBot: !!x.honeypot };
}

// recent = Calculator Requests rows created today matching this email or IP hash.
function rateLimited(recent, email, ipHash) {
  const byEmail = recent.filter((r) => String(r.Email || '').toLowerCase() === email).length;
  const byIp = ipHash ? recent.filter((r) => r['IP hash'] === ipHash).length : 0;
  return byEmail >= LIMIT_PER_DAY || byIp >= LIMIT_PER_DAY;
}

// Is the verification email allowed to go out? Off until the domain is verified (only Bilal's own inbox for testing).
function sendingAllowed(S, email, testInbox) {
  if (String(S.website_calculator || 'auto').toLowerCase() === 'off') return false;
  const verified = S.domain_status === 'Verified' && S.email_from && !/@resend\.dev/i.test(S.email_from);
  return verified || String(email).toLowerCase() === String(testInbox).toLowerCase();
}

function checkCode(row, code, salt, now) {
  if (!row) return { ok: false, reason: 'expired', message: 'That code has expired. Please request a new one.' };
  if (row.Verified) return { ok: false, reason: 'used', message: 'That code has already been used. Please request a new one.' };
  if (Date.parse(row.Expires) < (now || Date.now())) return { ok: false, reason: 'expired', message: 'That code has expired (codes last 15 minutes). Please request a new one.' };
  const attempts = Number(row.Attempts) || 0;
  if (attempts >= MAX_ATTEMPTS) return { ok: false, reason: 'locked', message: 'Too many wrong attempts. Please request a new code.' };
  if (hash(String(code || '').trim(), salt) !== row['Code hash']) {
    const left = MAX_ATTEMPTS - attempts - 1;
    return { ok: false, reason: 'wrong', attempts: attempts + 1, message: left > 0 ? `That code is not right. ${left} attempt${left === 1 ? '' : 's'} left.` : 'That code is not right, and that was the last attempt. Please request a new code.' };
  }
  return { ok: true };
}

function results(services) {
  const r = P.websiteRanges(services);
  return {
    setupFrom: r.setupFrom, monthlyFrom: r.monthlyFrom, packageName: r.packageName, services: r.services, packages: r.allPackages,
    note: r.note,
    cta: 'Get your exact quote with a Finance Ops Audit – £100 (normally £750). Qualifying businesses may receive it free.',
  };
}

function codeEmail(name, code) {
  const first = String(name || '').split(' ')[0] || 'there';
  const text = `Hi ${first},\n\nYour Keystone verification code is ${code}\n\nIt lasts 15 minutes. If you did not ask for an estimate, ignore this email.\n\nKeystone`;
  const html = `<div style="font-family:Arial,sans-serif;max-width:520px"><p>Hi ${first.replace(/[<>&"]/g, '')},</p><p>Your Keystone verification code is</p><p style="font-size:28px;letter-spacing:6px;font-weight:bold">${code}</p><p>It lasts 15 minutes. If you did not ask for an estimate, ignore this email.</p><p>Keystone</p></div>`;
  return { subject: `Your Keystone code: ${code}`, text, html };
}

module.exports = { LIMIT_PER_DAY, CODE_MINUTES, MAX_ATTEMPTS, BANDS, SERVICE_KEYS, FREE_MAIL, hash, randomCode, randomId, parseBody, clientIp, isFreeMail, validateStart, rateLimited, sendingAllowed, checkCode, results, codeEmail };

  },
  'pricing': function (module, exports, require) {
'use strict';
// Keystone's APPROVED prices (docs/PRICING.md, 9 Nov 2026). One source of truth for the audit, proposals,
// agents and the website calculator. Change docs/PRICING.md and this file together.

const SERVICES = ['invoicing', 'phone', 'quotes', 'reporting'];
const SERVICE_NAMES = {
  invoicing: 'Invoice Automation',
  phone: 'AI Phone Booking',
  quotes: 'Quote Calculator',
  reporting: 'Reporting Dashboard',
  monitoring: 'Monthly Operations Management',
};
const SERVICE_DESCRIPTIONS = {
  invoicing: 'Invoices auto-drafted in Xero when a job is completed, plus payment chasing',
  phone: 'Answers calls, books jobs, flags urgent calls and complaints',
  quotes: 'Instant quotes by phone, form or manually',
  reporting: 'Live figures plus a weekly money email',
};

const PRICING = {
  setup: { invoicing: 1750, phone: 1250, quotes: 1250, reporting: 1500 },
  setupDiscount: { 1: 0, 2: 0.10, 3: 0.15, 4: 0.20 },
  packages: [
    { key: 'starter', name: 'Starter', base: 750, services: 1, includes: '1 core service + monitoring and fixes' },
    { key: 'growth', name: 'Growth', base: 1500, services: 3, includes: '3 core services + monitoring and fixes + monthly review call' },
    { key: 'complete', name: 'Complete', base: 2500, services: 4, includes: 'All 4 core services + monitoring and fixes + monthly review call + a custom AI agent built for your business, quarterly growth review and 4-hour priority response' },
  ],
  // Monthly packages only (setup never changes with size). Fixed bands, never case by case.
  bands: [
    { key: '500k-1m', label: '£500k–£1M', mult: 0.8 },
    { key: '1m-3m', label: '£1M–£3M', mult: 1.0 },
    { key: '3m-10m', label: '£3M–£10M', mult: 1.5 },
  ],
  audit: { worth: 750, paid: 100, note: 'Credited against setup if you sign within 30 days.' },
  pilot: { auditFree: true, setupDiscount: 0.5, minTermMonths: 3, note: 'First client only: free audit and 50% off setup in exchange for a written case study and testimonial.' },
  callMinutesIncluded: 500,
  minTermMonths: 3,
};

// Old band names (earlier forms) -> current bands.
const BAND_ALIASES = { under500k: 'under500k', '500k-2m': '500k-1m', '2m-5m': '1m-3m', '5m-10m': '3m-10m', '10mplus': 'over10m', '500k-1m': '500k-1m', '1m-3m': '1m-3m', '3m-10m': '3m-10m', over10m: 'over10m' };
const BAND_LABELS = { under500k: 'Under £500k', '500k-1m': '£500k–£1M', '1m-3m': '£1M–£3M', '3m-10m': '£3M–£10M', over10m: 'Over £10M' };

function bandOf(revenueBand) { return BAND_ALIASES[String(revenueBand || '').toLowerCase()] || '1m-3m'; }
function bandMultiplier(revenueBand) {
  const k = bandOf(revenueBand);
  const b = PRICING.bands.find((x) => x.key === k);
  if (b) return { mult: b.mult, band: k, outOfRange: false };
  // Outside the three bands: use the nearest band and say so (Bilal decides).
  return { mult: k === 'under500k' ? 0.8 : 1.5, band: k, outOfRange: true };
}

function packageFor(serviceCount) {
  const n = Math.max(1, Math.min(4, Number(serviceCount) || 1));
  return n === 1 ? PRICING.packages[0] : n <= 3 ? PRICING.packages[1] : PRICING.packages[2];
}
function packagePrice(pkg, revenueBand) {
  const p = typeof pkg === 'string' ? PRICING.packages.find((x) => x.key === pkg || x.name === pkg) : pkg;
  return Math.round(p.base * bandMultiplier(revenueBand).mult);
}

function setupQuote(serviceKeys, { pilot = false } = {}) {
  const keys = [...new Set(serviceKeys || [])].filter((k) => PRICING.setup[k] !== undefined);
  const lines = keys.map((k) => ({ key: k, name: SERVICE_NAMES[k], fee: PRICING.setup[k] }));
  const gross = lines.reduce((s, l) => s + l.fee, 0);
  const discountPct = (PRICING.setupDiscount[keys.length] || 0) * 100;
  let total = gross * (1 - discountPct / 100);
  if (pilot) total *= 1 - PRICING.pilot.setupDiscount;
  return { lines, gross, discountPct, pilot, total: Math.round(total * 100) / 100 };
}

// Full proposal pricing: setup (with discount), the package for the number of services, the band price,
// and the sense check (monthly fee <= about one-third of the monthly loss the audit found).
function priceProposal(serviceKeys, { revenue, monthlyLoss, pilot = false } = {}) {
  const keys = [...new Set(serviceKeys || [])].filter((k) => SERVICES.includes(k));
  const pkg = packageFor(keys.length || 1);
  const band = bandMultiplier(revenue);
  const monthly = packagePrice(pkg, revenue);
  const setup = setupQuote(keys, { pilot });
  const loss = Number(monthlyLoss) || 0;
  const senseCheck = { monthlyFee: monthly, monthlyLoss: Math.round(loss), limit: Math.round(loss / 3), ok: loss > 0 ? monthly <= loss / 3 * 1.05 : null };
  return {
    services: keys, package: { ...pkg, price: monthly }, band: { key: band.band, label: BAND_LABELS[band.band], mult: band.mult, outOfRange: band.outOfRange },
    setup, audit: { ...PRICING.audit, offer: pilot ? 'Free (pilot)' : null }, senseCheck,
    terms: `Minimum term ${PRICING.minTermMonths} months, then monthly rolling. AI phone call costs above ${PRICING.callMinutesIncluded} minutes a month are passed on at cost.`,
  };
}

// What the website calculator shows after email verification: "from" figures at the ×1.0 band only.
function websiteRanges(serviceKeys) {
  const keys = [...new Set(serviceKeys || [])].filter((k) => SERVICES.includes(k));
  const use = keys.length ? keys : SERVICES;
  const setupFrom = keys.length ? setupQuote(keys).total : Math.min(...Object.values(PRICING.setup));
  const pkg = packageFor(keys.length || 1);
  return { services: keys.map((k) => SERVICE_NAMES[k]), setupFrom: Math.round(setupFrom), monthlyFrom: pkg.base, packageName: pkg.name, allPackages: PRICING.packages.map((p) => ({ name: p.name, from: p.base, includes: p.includes })), note: 'Exact price depends on business size.', considered: use.length };
}

// Audit offer from the 3 checks. Free only for High value leads; everything else (and time-wasters) £100.
function auditOffer({ fit, timing, pain, affordable, urgent, recurring, timeWaster }) {
  const high = !!(fit && timing && pain && affordable && urgent && recurring) && !timeWaster;
  return { leadValue: high ? 'High' : 'Standard', auditOffer: high ? 'Free' : '£100',
    shownAs: high ? 'Free Finance Ops Audit – worth £750' : 'Finance Ops Audit – £100 (87% off – normally £750)' };
}

module.exports = { SERVICES, SERVICE_NAMES, SERVICE_DESCRIPTIONS, PRICING, BAND_LABELS, bandOf, bandMultiplier, packageFor, packagePrice, setupQuote, priceProposal, websiteRanges, auditOffer };

  },
  'opsmanager': function (module, exports, require) {
'use strict';
// Keystone Ops Manager: morning/evening summaries, instant notices for key moments,
// and YES/NO approvals (SMS reply once Twilio has a number; email links until then).

const { escapeHtml: e } = require('./log');

function settingsMap(records) {
  const S = {};
  for (const r of records || []) { const f = r.fields || r; if (f.Setting) S[f.Setting] = String(f.Value || '').trim(); }
  return S;
}

// Which channel(s) to use for Bilal. Business escalations use the same SMS switch.
function channels(S) {
  const smsReady = !!(S.twilio_from && S.alert_sms_to);
  const mode = (S.ops_channel || 'auto').toLowerCase();
  if (mode === 'email' || !smsReady) return { sms: false, email: true, smsReady };
  if (mode === 'both') return { sms: true, email: true, smsReady };
  return { sms: true, email: false, smsReady };
}

function approvalCode() { return String(Math.floor(1000 + Math.random() * 9000)); }

// "YES 4821", "y 4821", "no4821", "4821 yes" -> {decision, code}
function parseReply(text) {
  const t = String(text || '').trim().toLowerCase();
  const code = (t.match(/\b(\d{4})\b/) || [])[1] || null;
  let decision = null;
  if (/\b(yes|y|approve|ok|okay|go)\b/.test(t)) decision = 'yes';
  if (/\b(no|n|reject|stop|cancel)\b/.test(t)) decision = decision ? null : 'no';
  return { decision, code };
}

const KIND_LABEL = {
  urgent_call: 'URGENT CALL', complaint: 'COMPLAINT', message: 'Message', quote_approval: 'Quote to approve',
  invoice_review: 'Invoice to review', failure: 'Workflow failure', info: 'Update', booking: 'New booking',
};

function smsText(n, code) {
  const head = `${KIND_LABEL[n.kind] || 'Keystone'}${n.clientName ? ' - ' + n.clientName : ''}: `;
  const tail = code ? ` Reply YES ${code} or NO ${code}.` : '';
  return (head + (n.text || n.title || '')).slice(0, 320 - tail.length) + tail;
}

function emailHtml(n, links) {
  const btn = (href, label, colour) => `<a href="${e(href)}" style="display:inline-block;background:${colour};color:#fff;padding:12px 18px;border-radius:6px;text-decoration:none;margin-right:8px">${label}</a>`;
  return `<div style="font-family:Arial,sans-serif;max-width:620px">
<h2 style="margin:0 0 8px;color:${n.kind === 'urgent_call' || n.kind === 'complaint' ? '#b91c1c' : '#1F3A5F'}">${e(KIND_LABEL[n.kind] || 'Keystone')}${n.clientName ? ' - ' + e(n.clientName) : ''}</h2>
<p style="font-size:15px;white-space:pre-wrap">${e(n.text || '')}</p>
${links ? `<p>${btn(links.yes, 'YES', '#059669')}${btn(links.no, 'NO', '#6b7280')}</p><p style="font-size:12px;color:#6b7280">Approval code ${e(links.code)}. Once SMS is set up you can also reply to the text with YES ${e(links.code)} or NO ${e(links.code)}.</p>` : ''}
<p style="font-size:12px;color:#6b7280">Keystone Ops Manager</p></div>`;
}

// ---------- summaries ----------
function inWindow(ts, from, to) { const t = Date.parse(ts); return t >= from.getTime() && t < to.getTime(); }
const f = (r) => (r && r.fields ? r.fields : r || {});
const sel = (v) => (v && v.name) || v || '';

function summarise({ logs = [], calls = [], quotes = [], reviews = [], approvals = [], clients = [] }, from, to) {
  const L = logs.map(f).filter((r) => inWindow(r['Timestamp'], from, to));
  const C = calls.map(f).filter((r) => inWindow(r['Timestamp'], from, to));
  const Q = quotes.map(f).filter((r) => inWindow(r['Created'], from, to));
  const count = (arr, pred) => arr.filter(pred).length;
  const nameOf = (id) => (clients.map(f).find((c) => c['Client ID'] === id) || {})['Client name'] || id || 'Keystone';
  const failures = L.filter((r) => sel(r['Outcome']) === 'Escalated' && sel(r['Service']) === 'monitor');
  return {
    invoicesDrafted: count(L, (r) => String(r['Event']).startsWith('invoice_') && sel(r['Outcome']) === 'Draft created'),
    invoicesToReview: count(L, (r) => String(r['Event']).startsWith('invoice_') && sel(r['Outcome']) === 'Sent to review'),
    calls: C.length,
    bookings: count(C, (r) => ['Booking', 'Reschedule'].includes(sel(r['Category']))),
    urgent: C.filter((r) => sel(r['Category']) === 'Urgent').map((r) => `${nameOf(r['Client ID'])}: ${String(r['Summary'] || '').slice(0, 80)}`),
    complaints: C.filter((r) => sel(r['Category']) === 'Complaint').map((r) => `${nameOf(r['Client ID'])}: ${String(r['Summary'] || '').slice(0, 80)}`),
    quotes: Q.length,
    quotesValue: Math.round(Q.reduce((s, r) => s + (Number(r['Total']) || 0), 0)),
    failures: failures.map((r) => `${r['Reference'] || 'workflow'} (${nameOf(r['Client ID'])})`),
    openReviews: reviews.map(f).filter((r) => sel(r['Status']) === 'Open').length,
    pendingApprovals: approvals.map(f).filter((r) => sel(r['Status']) === 'Pending').map((r) => ({ code: r['Code'], summary: r['Summary'] })),
    activeClients: clients.map(f).filter((c) => sel(c['Status']) === 'Active').length,
  };
}

function summaryText(kind, s, dateLabel) {
  const lines = [];
  lines.push(kind === 'morning' ? `Good morning. Overnight and yesterday evening (${dateLabel}):` : `End of day (${dateLabel}):`);
  lines.push(`- ${s.activeClients} active clients`);
  lines.push(`- Invoices drafted: ${s.invoicesDrafted}${s.invoicesToReview ? ` (${s.invoicesToReview} need review)` : ''}`);
  lines.push(`- Calls: ${s.calls}, bookings: ${s.bookings}`);
  lines.push(`- Quotes: ${s.quotes}${s.quotesValue ? ` (£${s.quotesValue.toLocaleString('en-GB')})` : ''}`);
  if (s.urgent.length) lines.push(`- URGENT calls: ${s.urgent.join('; ')}`);
  if (s.complaints.length) lines.push(`- Complaints: ${s.complaints.join('; ')}`);
  if (s.failures.length) lines.push(`- Failures: ${s.failures.join('; ')}`);
  lines.push(`- Open review items: ${s.openReviews}`);
  if (s.pendingApprovals.length) lines.push(`- Waiting for your YES/NO: ${s.pendingApprovals.map((a) => `#${a.code} ${String(a.summary).slice(0, 60)}`).join('; ')}`);
  if (!s.urgent.length && !s.complaints.length && !s.failures.length && !s.openReviews && !s.pendingApprovals.length) lines.push('Nothing needs you right now.');
  return lines.join('\n');
}

function summarySms(kind, s) {
  const needs = s.urgent.length + s.complaints.length + s.failures.length + s.openReviews + s.pendingApprovals.length;
  return `Keystone ${kind === 'morning' ? 'AM' : 'PM'}: ${s.invoicesDrafted} invoices, ${s.calls} calls/${s.bookings} bookings, ${s.quotes} quotes. ${needs ? needs + ' need you' + (s.pendingApprovals.length ? ' (approvals: ' + s.pendingApprovals.map((a) => a.code).join(', ') + ')' : '') : 'All clear.'}`.slice(0, 320);
}

module.exports = { settingsMap, channels, approvalCode, parseReply, smsText, emailHtml, summarise, summaryText, summarySms, KIND_LABEL };

  },
  'log': function (module, exports, require) {
'use strict';
// One shape for every Agent Log row. Every agent or workflow decision goes through this.

const OPS_EMAIL = 'khan.bilalbk408@gmail.com'; // Bilal (Resend account owner, so test-sender mail is delivered)

// Conservative admin-time estimates (minutes a person would have spent). Used for value reports.
const MINUTES_SAVED = {
  invoice_draft_created: 12,
  invoice_agent_fixed: 20,
  invoice_queued: 2,
  call_handled: 5,
  booking_made: 8,
  reschedule: 6,
  urgent_escalated: 5,
  complaint_logged: 8,
  message_taken: 4,
  quote_drafted: 25,
  issue_auto_fixed: 20,
  weekly_report: 45,
  monthly_report: 90,
};

function logRecord({ clientId, service, event, decision, reasoning, outcome, confidence, reference, workflow, executionId, details, now }) {
  const minutes = MINUTES_SAVED[event] || 0;
  const summary = `[${clientId || 'keystone'}] ${service}: ${event}${outcome ? ' -> ' + outcome : ''}`.slice(0, 250);
  return {
    'Summary': summary,
    'Client ID': clientId || '',
    'Service': service,
    'Event': event,
    'Decision': decision || '',
    'Reasoning': reasoning || '',
    'Outcome': outcome || 'Success',
    'Confidence': typeof confidence === 'number' ? Math.max(0, Math.min(1, confidence)) : null,
    'Reference': reference || '',
    'Minutes saved': ['Success', 'Draft created', 'Auto-fixed', 'Escalated'].includes(outcome || 'Success') ? minutes : 0,
    'Timestamp': (now || new Date()).toISOString(),
    'Workflow': workflow || '',
    'Execution ID': executionId ? String(executionId) : '',
    'Details JSON': details ? JSON.stringify(details).slice(0, 90000) : '',
  };
}

function escapeHtml(s) {
  return String(s === undefined || s === null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

// Airtable filterByFormula string literal escaping.
function formulaString(s) {
  return "'" + String(s || '').replace(/\\/g, '\\\\').replace(/'/g, "\\'") + "'";
}

module.exports = { OPS_EMAIL, MINUTES_SAVED, logRecord, escapeHtml, formulaString };

  },
  'requests': function (module, exports, require) {
'use strict';
// Request builders for the HTTP Request nodes. Each returns {url, method, body, tenantId?}
// and goes on an item as $json.req. Credentials come from n8n, never from here.

const { formulaString } = require('./log');

const AIRTABLE_API = 'https://api.airtable.com/v0';
// Change once a domain is verified in Resend (BLOCKERS.md). resend.dev only delivers to the Resend account owner.
const EMAIL_FROM = 'Keystone <onboarding@resend.dev>';

function qs(pairs) {
  // n8n's Code sandbox has no URLSearchParams, so encode by hand.
